void LoadState(){if(!string.IsNullOrWhiteSpace(Storage)){var sections=Storage.Split(new string[]{"||"},StringSplitOptions.None);if(sections.Length>0){var parts=sections[0].Split('|');if(parts.Length>=6){float f;if(float.TryParse(parts[0],out f))_targetSpeed=f;_cruiseEnabled=(parts[1]=="True");if(float.TryParse(parts[2],out f))_vertTargetSpeed=f;_vertControlEnabled=(parts[3]=="True");_alignActive=(parts[4]=="True");if(float.TryParse(parts[5],out f))_pitchOffset=f;if(parts.Length>=7)_showHudTarget=(parts[6]=="True");if(parts.Length>=8&&float.TryParse(parts[7],out f))_hudZoom=f;if(parts.Length>=9)int.TryParse(parts[8],out _trackingMode);if(parts.Length>=10)_worldRelativeVert=(parts[9]=="True");if(parts.Length>=11)_hudCleanMode=(parts[10]=="True");if(parts.Length>=12)_isRocketMode=(parts[11]=="True");if(parts.Length>=13)_alignProgradeActive=(parts[12]=="True");if(parts.Length>=14)_alignRetrogradeActive=(parts[13]=="True");if(parts.Length>=15)_isDropMode=(parts[14]=="True");if(parts.Length>=16&&float.TryParse(parts[15],out f))_hudBrightness=f;UpdateHudColors();}}if(sections.Length>1&&!string.IsNullOrWhiteSpace(sections[1])){_dockProfiles.Clear();var profiles=sections[1].Split('#');for(int i=0;i<profiles.Length;i++){var p=profiles[i].Split(';');if(p.Length>=11){DockProfile prof=new DockProfile();prof.Name=p[0];long.TryParse(p[1],out prof.ShipConnId);double x,y,z,fx,fy,fz,ux,uy,uz;if(double.TryParse(p[2],out x)&&double.TryParse(p[3],out y)&&double.TryParse(p[4],out z))prof.TargetPos=new Vector3D(x,y,z);if(double.TryParse(p[5],out fx)&&double.TryParse(p[6],out fy)&&double.TryParse(p[7],out fz))prof.TargetForward=new Vector3D(fx,fy,fz);if(double.TryParse(p[8],out ux)&&double.TryParse(p[9],out uy)&&double.TryParse(p[10],out uz))prof.TargetUp=new Vector3D(ux,uy,uz);if(p.Length>=22){long.TryParse(p[11],out prof.CarrierEntityId);double lx,ly,lz,lfx,lfy,lfz,lux,luy,luz;if(double.TryParse(p[12],out lx)&&double.TryParse(p[13],out ly)&&double.TryParse(p[14],out lz))prof.LocalPos=new