void UpdateHUDTextSummary(){if(_seat==null){_hudTextSummary="=== SYSTEM STATUS ===\nMODE: SYSTEM HALT - NO SEAT\n";return;}Vector3D velocity=_seat.GetShipVelocities().LinearVelocity;double speed=velocity.Length();string alignStr=_autoDockActive?$"[ AUTODOCK STAGE {_autoDockStage} ]":(_elevatorActive?$"[ POS: {_activeElevatorStop?.Name?.ToUpper()} ]":(_panActive?"[ PAN TRANSLATION ACTIVE ]":(_alignTargetActive?"[ ALIGN: TO HUD TARGET ]":(_alignProgradeActive?"[ ALIGN: PROGRADE ]":(_alignRetrogradeActive?"[ ALIGN: RETROGRADE ]":(_planeFlightActive?(Math.Abs(_targetBankAngle)>0.01?$"[ PLANE FLIGHT: BANK ({_targetBankAngle:0}°) ]":"[ PLANE FLIGHT ACTIVE ]"):(_alignActive?(_isRocketMode?$"[ ROCKET ALIGN: ON ({_pitchOffset}°) ]":$"[ ALIGN: ON ({_pitchOffset}°) ]"):(_isFlipping?(_flipMode==1?"[ FLIP & BURN ACTIVE ]":"[ FLIP & GLIDE ACTIVE ]"):(_isRotating?"[ ROTATING TO TARGET ]":"[ ALIGN: OFF ]")))))))));string sysLoadText="SYS LOAD: "+Runtime.LastRunTimeMs.ToString("0.00")+" ms";string speedTextStr="SPD: "+speed.ToString("0.0")+" m/s";_stringBuffer.Clear();if(_routePaused)_stringBuffer.Append("[ ROUTE PAUSED ]");else if(_cruiseEnabled){_stringBuffer.Append("[ CRS: ").Append(_targetSpeed.ToString("0.0")).Append(" m/s ]");double forwardSpeed=Vector3Dot(velocity,_seat.WorldMatrix.Forward),speedError=_targetSpeed-forwardSpeed;if(Math.Abs(speedError)>0.5){float activeThrust=0f;for(int i=0;i<_thrustersForward.Count;i++)if(_thrustersForward[i].IsWorking)activeThrust+=_thrustersForward[i].MaxEffectiveThrust;float mass=_seat.CalculateShipMass().PhysicalMass;if(activeThrust>100&&mass>0){TimeSpan ts=TimeSpan.FromSeconds(Math.Abs(speedError)/(activeThrust/mass));_stringBuffer.Append("\nETA: ").Append(ts.TotalMinutes>=1?ts.ToString(@"mm\:ss"):ts.Seconds.ToString()+"s");}}}else _stringBuffer.Append("[ CRS: OFF (set: ").Append(_targetSpeed.ToString("0.0")).Append(" ) ]");string crsStatusText=_stringBuffer.ToString();bool hasTarget=false;if(_showHudTarget){if(_trackingMode==0&&_waypoints.Count>0&&_currentIndex<_waypoints.Count)hasTarget=true;else if(_trackingMode==1&&_trackedIgcId!=0&&_remoteShips.ContainsKey(_trackedIgcId))hasTarget=true;}System.Text.StringBuilder sb=new System.Text.StringBuilder();sb.AppendLine("=== SYSTEM STATUS ===");sb.AppendLine("MODE: NORMAL FLIGHT");sb.AppendLine($"Control Seat: {_seat.CustomName}");sb.AppendLine($"Piloted: {(_seat.IsUnderControl?"YES":"NO")}");sb.AppendLine(alignStr);sb.AppendLine(_hudHydro);sb.AppendLine(_hudPower);sb.AppendLine(sysLoadText);if(!_showHudTarget)sb.AppendLine("[HUD OFF]");sb.AppendLine();sb.AppendLine("=== FLIGHT TELEMETRY ===");sb.AppendLine(speedTextStr);sb.AppendLine(crsStatusText);if(_routeActive)sb.AppendLine($"ROUTE PROGRESS: [{_routeCurrentStep+1} / {_routeIndices.Count}]"+(_routePaused?" (PAUSED)":""));sb.AppendLine();if(!string.IsNullOrEmpty(_hudExtWarning)){sb.AppendLine("=== ALERTS ===");sb.AppendLine(_hudExtWarning);sb.AppendLine();}sb.AppendLine("=== NAVIGATION ===");sb.AppendLine($"Target Source: {(_trackingMode==0?"GPS ROUTE":"IGC NETWORK")}");sb.AppendLine($"Total Stored Waypoints: {_waypoints.Count}");if(hasTarget&&!string.IsNullOrEmpty(_hudExtTarget)&&!_routePaused){sb.AppendLine(_hudExtTarget);sb.AppendLine();}sb.AppendLine(_hudExtFlightAssist);_hudTextSummary=sb.ToString();}
void ProcessAutoDock(Vector3D velocity){if(!_autoDockActive||_activeDockProfile==null||_seat==null)return;IMyShipConnector localConn=null;for(int i=0;i<_connectors.Count;i++){if(_connectors[i].EntityId==_activeDockProfile.ShipConnId){localConn=_connectors[i];break;}}if(localConn==null&&_connectors.Count>0)localConn=_connectors[0];if(localConn==null){Main("ABORT",UpdateType.Terminal);return;}Vector3D dynamicTargetPos=_activeDockProfile.TargetPos;Vector3D dynamicTargetForward=_activeDockProfile.TargetForward;Vector3D dynamicTargetUp=_activeDockProfile.TargetUp;if(_activeDockProfile.IsDynamic&&_remoteShips.ContainsKey(_activeDockProfile.CarrierEntityId)){RemoteShip carrier=_remoteShips[_activeDockProfile.CarrierEntityId];MatrixD carrierWorld=MatrixD.CreateWorld(carrier.Position,carrier.Forward,carrier.Up);MatrixD localConnMatrix=MatrixD.CreateWorld(_activeDockProfile.LocalPos,_activeDockProfile.LocalForward,_activeDockProfile.LocalUp);MatrixD dynamicTargetConnWorld=localConnMatrix*carrierWorld;dynamicTargetPos=dynamicTargetConnWorld.Translation;dynamicTargetForward=dynamicTargetConnWorld.Forward;dynamicTargetUp=dynamicTargetConnWorld.Up;}MatrixD targetConnWorld=MatrixD.CreateWorld(dynamicTargetPos,-dynamicTargetForward,dynamicTargetUp);MatrixD localConnInSeat=localConn.WorldMatrix*MatrixD.Invert(_seat.WorldMatrix);MatrixD desSeatWorld=MatrixD.Invert(localConnInSeat)*targetConnWorld;_targetOrientation=QuaternionD.CreateFromRotationMatrix(desSeatWorld);_isRotating=true;Vector3D connPos=localConn.GetPosition();Vector3D approachPos=dynamicTargetPos+(dynamicTargetForward*2.5);Vector3D gravity=_seat.GetNaturalGravity();double mass=_seat.CalculateShipMass().PhysicalMass;if(_autoDockStage==1){Vector3D toApproach=approachPos-connPos;double dist=toApproach.Length();QuaternionD currentOrientation=QuaternionD.CreateFromRotationMatrix(_seat.WorldMatrix);QuaternionD errorQ=_targetOrientation*QuaternionD.Inverse(currentOrientation);Vector3D worldAxis;double angleError;errorQ.GetAxisAngle(out worldAxis,out angleError);if(angleError>Math.PI)angleError-=2*Math.PI;double currentSpeed=velocity.Length();if(dist<=0.15&&Math.Abs(angleError)<=CUTOFF_RADIANS&&currentSpeed<=0.30){_autoDockStage=2;return;}double speedLimit=Math.Min(5.0,Math.Sqrt(2.0*dist));Vector3D targetVel=(dist>0.02)?(Vector3D.Normalize(toApproach)*speedLimit):Vector3D.Zero;Vector3D velError=targetVel-velocity;Vector3D accelVec=(velError*2.5)-gravity;ApplyForceGroup(_thrustersForward,_thrustersBackward,Vector3Dot(accelVec,_seat.WorldMatrix.Forward)*mass);ApplyForceGroup(_thrustersUp,_thrustersDown,Vector3Dot(accelVec,_seat.WorldMatrix.Up)*mass);ApplyForceGroup(_thrustersRight,_thrustersLeft,Vector3Dot(accelVec,_seat.WorldMatrix.Right)*mass);}else if(_autoDockStage==2){if(localConn.Status==MyShipConnectorStatus.Connectable||localConn.Status==MyShipConnectorStatus.Connected){localConn.Connect();Main("DOCK",UpdateType.Terminal);_autoDockActive=false;_autoDockStage=0;_activeDockProfile=null;return;}Vector3D toTarget=dynamicTargetPos-connPos;double distParallel=Vector3Dot(toTarget,dynamicTargetForward);Vector3D parallelComp=dynamicTargetForward*distParallel;Vector3D transverseOffset=toTarget-parallelComp;double tLen=transverseOffset.Length();Vector3D transverseVel=(tLen>0.001)?(transverseOffset/tLen)*Math.Min(1.0,tLen*2.0):Vector3D.Zero;Vector3D targetVel=(-dynamicTargetForward*0.25)+transverseVel;Vector3D velError=targetVel-velocity;Vector3D accelVec=(velError*2.5)-gravity;ApplyForceGroup(_thrustersForward,_thrustersBackward,Vector3Dot(accelVec,_seat.WorldMatrix.Forward)*mass);ApplyForceGroup(_thrustersUp,_thrustersDown,Vector3Dot(accelVec,_seat.WorldMatrix.Up)*mass);ApplyForceGroup(_thrustersRight,_thrustersLeft,Vector3Dot(accelVec,_seat.WorldMatrix.Right)*mass);}}
void ProcessPanControl(Vector3D velocity){if(!_panActive||_seat==null)return;Vector3D toTarget=_panTargetPos-_seat.GetPosition();double distRemaining=Vector3Dot(toTarget,_panDirVec);if(distRemaining<=0.25){_panActive=false;ResetThrusterOverrides();_seat.DampenersOverride=true;return;}double mass=_seat.CalculateShipMass().PhysicalMass;double targetSpeed=Math.Min((double)_panSpeed,Math.Sqrt(5.0*Math.Max(0.0,distRemaining)));Vector3D targetVel=_panDirVec*targetSpeed;Vector3D velError=targetVel-velocity;Vector3D gravity=_seat.GetNaturalGravity();Vector3D accelVec=(velError*2.5)-gravity;ApplyForceGroup(_thrustersForward,_thrustersBackward,Vector3Dot(accelVec,_seat.WorldMatrix.Forward)*mass);ApplyForceGroup(_thrustersUp,_thrustersDown,Vector3Dot(accelVec,_seat.WorldMatrix.Up)*mass);ApplyForceGroup(_thrustersRight,_thrustersLeft,Vector3Dot(accelVec,_seat.WorldMatrix.Right)*mass);}
void ProcessElevatorControl(Vector3D velocity){if(!_elevatorActive||_activeElevatorStop==null||_seat==null)return;Vector3D currentPos=_seat.GetPosition();Vector3D toTarget=_activeElevatorStop.TargetPos-currentPos;double distRemaining=toTarget.Length();if(distRemaining<=0.10&&velocity.Length()<=0.15){_elevatorActive=false;StopRotation();ResetThrusterOverrides();if(_seat!=null){_seat.DampenersOverride=true;_seat.HandBrake=true;}return;}double mass=_seat.CalculateShipMass().PhysicalMass;Vector3D gravity=_seat.GetNaturalGravity();double maxSpeed=(_targetSpeed>0f)?_targetSpeed:15.0;double targetSpeed=Math.Min(maxSpeed,Math.Sqrt(3.0*Math.Max(0.0,distRemaining)));Vector3D targetVel=(distRemaining>0.001)?(Vector3D.Normalize(toTarget)*targetSpeed):Vector3D.Zero;Vector3D velError=targetVel-velocity;Vector3D accelVec=(velError*2.5)-gravity;ApplyForceGroup(_thrustersForward,_thrustersBackward,Vector3Dot(accelVec,_seat.WorldMatrix.Forward)*mass);ApplyForceGroup(_thrustersUp,_thrustersDown,Vector3Dot(accelVec,_seat.WorldMatrix.Up)*mass);ApplyForceGroup(_thrustersRight,_thrustersLeft,Vector3Dot(accelVec,_seat.WorldMatrix.Right)*mass);}
void ApplyForceGroup(List<IMyThrust>pos,List<IMyThrust>neg,double force){if(force>0.1){float maxT=0f;for(int i=0;i<pos.Count;i++)if(pos[i].IsWorking)maxT+=pos[i].MaxEffectiveThrust;float cmd=maxT>0?MathHelper.Clamp((float)(force/maxT),0.000001f,1f):0.000001f;for(int i=0;i<pos.Count;i++)pos[i].ThrustOverridePercentage=cmd;for(int i=0;i<neg.Count;i++)neg[i].ThrustOverridePercentage=0.000001f;}else if(force<-0.1){float maxT=0f;for(int i=0;i<neg.Count;i++)if(neg[i].IsWorking)maxT+=neg[i].MaxEffectiveThrust;float cmd=maxT>0?MathHelper.Clamp((float)(-force/maxT),0.000001f,1f):0.000001f;for(int i=0;i<neg.Count;i++)neg[i].ThrustOverridePercentage=cmd;for(int i=0;i<pos.Count;i++)pos[i].ThrustOverridePercentage=0.000001f;}else{for(int i=0;i<pos.Count;i++)pos[i].ThrustOverridePercentage=0.000001f;for(int i=0;i<neg.Count;i++)neg[i].ThrustOverridePercentage=0.000001f;}}
void ApplyThrustGroup(List<IMyThrust>pos,List<IMyThrust>neg,double error,double mass){ApplyForceGroup(pos,neg,error*mass*2.5);}
void ResetThrusterOverrides(){for(int i=0;i<_thrustersAll.Count;i++)if(_thrustersAll[i]!=null)_thrustersAll[i].ThrustOverridePercentage=0f;}
void ResetThrusters(List<IMyThrust>thrusters){for(int i=0;i<thrusters.Count;i++)if(thrusters[i]!=null)thrusters[i].ThrustOverridePercentage=0f;}
void UpdateManualInputs(){if(_seat!=null&&_seat.IsUnderControl){float targetPitch=_seat.RotationIndicator.X*SENSE_PITCH_YAW,targetYaw=_seat.RotationIndicator.Y*SENSE_PITCH_YAW,targetRoll=_seat.RollIndicator*SENSE_ROLL;_smoothedPitch+=(targetPitch-_smoothedPitch)*INPUT_SMOOTHING_ALPHA;_smoothedYaw+=(targetYaw-_smoothedYaw)*INPUT_SMOOTHING_ALPHA;_smoothedRoll+=(targetRoll-_smoothedRoll)*INPUT_SMOOTHING_ALPHA;}else{_smoothedPitch=0f;_smoothedYaw=0f;_smoothedRoll=0f;}}
void CalculateBraking(Vector3D velocity,double speed){_stopDist=0;_stopTime=0;_fatalDrift=false;float currentSpeed=(float)speed;if(currentSpeed<=0.1f||_seat==null)return;float mass=_seat.CalculateShipMass().PhysicalMass;Vector3D retroDir=-velocity;retroDir.Normalize();float maxBrakeThrust=0f;if(_isFlipping&&_flipMode==1){for(int i=0;i<_thrustersForward.Count;i++)if(_thrustersForward[i].IsFunctional)maxBrakeThrust+=_thrustersForward[i].MaxEffectiveThrust;}else{for(int i=0;i<_thrustersAll.Count;i++){if(_thrustersAll[i].IsFunctional){double dot=Vector3Dot(-_thrustersAll[i].WorldMatrix.Forward,retroDir);if(dot>0)maxBrakeThrust+=(float)(_thrustersAll[i].MaxEffectiveThrust*dot);}}}Vector3D netAcc=(retroDir*(mass>0?(maxBrakeThrust/mass):0f))+_seat.GetNaturalGravity();double netDecel=Vector3Dot(netAcc,retroDir);if(netDecel>0){_stopDist=(currentSpeed*currentSpeed)/(2*netDecel);_stopTime=currentSpeed/netDecel;}else _fatalDrift=true;}
void CycleIgcTarget(bool forward){if(_remoteShips.Count==0){_trackedIgcId=0;_currentIgcIndex=0;return;}List<long>keys=new List<long>(_remoteShips.Keys);if(_trackingMode==1&&_trackedIgcId!=0&&keys.Contains(_trackedIgcId)){int index=keys.IndexOf(_trackedIgcId);if(forward){_currentIgcIndex=index+1;if(_currentIgcIndex>=keys.Count)_currentIgcIndex=0;}else{_currentIgcIndex=index-1;if(_currentIgcIndex<0)_currentIgcIndex=keys.Count-1;}}else _currentIgcIndex=0;_trackedIgcId=keys[_currentIgcIndex];}
