void ProcessTargetAlignment(){if(_seat==null)return;Vector3D targetPos=Vector3Zero();bool hasTarget=false;if(_trackingMode==0&&_waypoints.Count>0&&_currentIndex<_waypoints.Count){targetPos=_waypoints[_currentIndex];hasTarget=true;}else if(_trackingMode==1&&_trackedIgcId!=0&&_remoteShips.ContainsKey(_trackedIgcId)){targetPos=_remoteShips[_trackedIgcId].Position;hasTarget=true;}if(!hasTarget){_alignTargetActive=false;_isRotating=false;return;}Vector3D shipPos=_seat.GetPosition(),forwardVector=targetPos-shipPos;if(forwardVector.LengthSquared()<1)return;forwardVector.Normalize();Vector3D upHint=_seat.WorldMatrix.Up;MatrixD targetMatrix=MatrixD.CreateWorld(shipPos,forwardVector,upHint);_targetOrientation=QuaternionD.CreateFromRotationMatrix(targetMatrix);_isRotating=true;}
